import json, math, sys
from pathlib import Path

LEVELS = [0.05, 0.25, 0.5, 0.75, 0.95]

def pinball_item(y, q, tau):
    y = 1.0 if y < 1 else float(y)
    q = float(q)
    if not math.isfinite(q) or q <= 0 or q > 1_000_000_000:
        raise ValueError(f'invalid quantile {q}')
    d = math.log(y) - math.log(q)
    return 2 * max(tau * d, (tau - 1) * d)

def load_forecast(path):
    obj = json.loads(Path(path).read_text())
    if list(obj.keys()) != ['hours']:
        raise ValueError(f'{path}: expected exactly one key hours')
    rows = obj['hours']
    if not isinstance(rows, list) or len(rows) != 23:
        raise ValueError(f'{path}: expected 23 hour rows')
    by = {}
    for row in rows:
        if set(row.keys()) != {'hour', 'q'}:
            raise ValueError(f'{path}: row keys must be hour and q only')
        h = row['hour']
        q = row['q']
        if h in by or h not in range(2, 25):
            raise ValueError(f'{path}: bad/duplicate hour {h}')
        if not (isinstance(q, list) and len(q) == 5):
            raise ValueError(f'{path}: q must have 5 values')
        prev = 0
        for v in q:
            if not isinstance(v, (int, float)) or isinstance(v, bool) or not math.isfinite(v) or v <= 0 or v > 1_000_000_000:
                raise ValueError(f'{path}: bad q value {v}')
            if v < prev:
                raise ValueError(f'{path}: q not nondecreasing')
            prev = v
        by[h] = [float(v) for v in q]
    return by

def grade(out_dir, answers_path):
    answers = json.loads(Path(answers_path).read_text())
    items = []
    per_case = {}
    all_valid = True
    for case_id, ans in answers.items():
        out = Path(out_dir) / f'{case_id}.out'
        y_by = {row['hour']: row['viewers'] for row in ans['hours']}
        try:
            if not out.is_file():
                raise ValueError('missing output')
            if out.stat().st_size > 65536:
                raise ValueError('output too large')
            fc = load_forecast(out)
            case_items = []
            for h in range(2, 25):
                y = y_by[h]
                if y is None:
                    continue
                q = fc[h]
                for tau, qv in zip(LEVELS, q):
                    case_items.append(pinball_item(y, qv, tau))
            loss = sum(case_items) / len(case_items)
            # typical miss on median
            miss = []
            cover = 0
            n = 0
            for h in range(2, 25):
                y = y_by[h]
                yy = 1.0 if y < 1 else float(y)
                med = fc[h][2]
                miss.append(abs(math.log(yy) - math.log(med)))
                if fc[h][0] <= yy <= fc[h][4]:
                    cover += 1
                n += 1
            m = sum(miss)/len(miss)
            typical = 100 * (math.exp(m) - 1)
            per_case[case_id] = {
                'valid': 1,
                'loss': round(loss, 6),
                'loss_exact': loss,
                'typical_miss_pct': typical,
                'coverage_90': cover / n,
            }
            items.extend(case_items)
        except Exception as e:
            all_valid = False
            # invalid: every quantile = hour-1 print? We need hour-1 from answers
            y1 = y_by[1]
            case_items = []
            for h in range(2, 25):
                y = y_by[h]
                for tau in LEVELS:
                    case_items.append(pinball_item(y, y1, tau))
            loss = sum(case_items)/len(case_items)
            per_case[case_id] = {'valid': 0, 'loss': round(loss, 6), 'loss_exact': loss, 'error': str(e)}
            items.extend(case_items)
    mean = sum(items)/len(items)
    return {
        'loss': round(mean, 6),
        'loss_exact': mean,
        'valid': 1 if all_valid else 0,
        'cases': per_case,
        'n_items': len(items),
    }

if __name__ == '__main__':
    out_dir = sys.argv[1]
    answers = sys.argv[2] if len(sys.argv)>2 else str(Path(__file__).with_name('practice-answers.json'))
    print(json.dumps(grade(out_dir, answers), indent=2))

